INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.117.0',
  '2026-10-06',
  'Пульт ТВ: разбор медиатеки по качеству и перестроенная панель плеера',
  E'В админке, на «Обслуживании», появился разбор медиатеки. Кнопка «🔍 Разобрать медиатеку» проходит по всем фильмам и сериалам и показывает, что записано плохо: ниже 720p, всего одна звуковая дорожка, вовсе без звука, приставка не играет как есть, жирный битрейт. Фильтры переключаются кнопками, у каждой видно, сколько всего попало; в строке — разрешение, кодеки, битрейт, дорожки и путь на диске.\n\nПанель плеера перестроена. Фильм или серия включается сразу, поэтому первой кнопкой стала «во весь экран» — и фокус при старте теперь на ней, достаточно нажать OK. Дальше воспроизведение, перемотка, серии и стоп.\n\nБлок музыки под фильм на странице плеера закрыт: ставят её редко, а место он занимал всегда. Открывается кнопкой «🎵» — сразу с выбором папки, и там же переехавший переключатель «Музыка на паузе». В режиме «Файлы» блок остался открытым: других органов управления музыкой там нет. Кнопка «Инфо» ужалась до значка.',
  E'quality.go, GET /api/admin/quality. Обход по ПЛИТКАМ, а не по файлам: у сериала разбирается первая серия — остальные той же раздачи устроены так же, а ffprobe по восьми тысячам файлов занял бы минуты ради того же ответа; разбор идёт через общий кэш probe.json, поэтому второй заход мгновенный. Фильтры считает страница из одного ответа: плиток десятки, и перебирать условия кнопками дешевле, чем гонять запрос на каждое. Ручка под PIN — список показывает пути на диске.\n\nПанель: порядок кнопок в разметке и есть порядок фокуса, showPlayer() как и раньше берёт первую, так что «во весь экран» получает фокус без отдельного кода. Значок — инлайновый SVG в .btn.icon (inline-flex, min-width 44px), по высоте совпадает с соседними кнопками.\n\nБлок музыки прячется в showPlayer() и открывается действием music(), которое заодно разворачивает выбор папки. setMode держит его открытым в «Файлах». Переключатель «Музыка на паузе» переехал в #mbar, поэтому обработчик data-a вешается селектором «#bar button, #musicpause», а не только на #bar — иначе кнопка молча перестала бы работать.\n\nПопутно «📂 Файлы» теперь переключает вкладку на медиатеку: из нового списка он вызывается вне её, и раньше нажатие просто перерисовывало «Обслуживание».\n\nПроверено в браузере: порядок кнопок и фокус при старте, геометрия значка (46×41 против 72×41 у соседней, по верху и низу совпадают), открытие и закрытие блока музыки с выбором, работа «Музыки на паузе» с нового места, все пять фильтров разбора и переход в файлы с возвратом. Тест quality_test.go.'
);
